"""Slope separation: certifying continuum many distinct unlimited hypernaturals.

For a real slope r > 0 let S_r be the germ of the staircase i |-> floor(i*r).
Two facts make the map r |-> S_r an order embedding of (0, infinity) into the
unlimited hypernaturals, and hence force the model to have exactly the
cardinality of the continuum:

  (1) S_r is unlimited: floor(i*r) exceeds any level c once i > (c+1)/r;
  (2) if r < s then floor(i*r) < floor(i*s) for every i > 1/(s-r).

Both bounds are explicit, so each separation is certified by a *finite*
computation: beyond the crossing index the coordinatewise inequality never
fails again, and a cofinite set of coordinates is large in every nonprincipal
ultrafilter.
"""

from __future__ import annotations

import math
from typing import List, Optional, Tuple


def staircase_value(r: float, i: int) -> int:
    """The i-th coordinate of the germ S_r."""
    return math.floor(i * r)


def theoretical_crossing(r: float, s: float) -> int:
    """Upper bound for the coordinate beyond which S_r < S_s pointwise."""
    if s <= r:
        raise ValueError("require r < s")
    return math.ceil(1.0 / (s - r))


def observed_crossing(r: float, s: float, horizon: int) -> Optional[int]:
    """Smallest N <= horizon with floor(i*r) < floor(i*s) for all N <= i <= horizon."""
    last_bad = -1
    for i in range(horizon + 1):
        if not staircase_value(r, i) < staircase_value(s, i):
            last_bad = i
    return None if last_bad >= horizon else last_bad + 1


def unlimited_certificate(r: float, level: int) -> int:
    """Coordinate beyond which the staircase S_r exceeds the standard `level`."""
    return math.ceil((level + 1) / r)


def separation_table(slopes: List[float], horizon: int = 4000) -> List[Tuple[float, float, int, Optional[int]]]:
    """For each consecutive pair of slopes, report the predicted and observed
    crossing indices.  Complexity: O(len(slopes) * horizon)."""
    rows: List[Tuple[float, float, int, Optional[int]]] = []
    ordered = sorted(slopes)
    for r, s in zip(ordered, ordered[1:]):
        bound = theoretical_crossing(r, s)
        window = max(horizon, 3 * bound + 10)   # always look past the guarantee
        rows.append((r, s, bound, observed_crossing(r, s, window)))
    return rows


def chain_is_strictly_increasing(slopes: List[float], horizon: int = 4000) -> bool:
    """Verify that the germs of the given slopes are pairwise distinct and
    strictly ordered -- i.e. that they are distinct unlimited hypernaturals."""
    ordered = sorted(slopes)
    return all(observed_crossing(r, s, max(horizon, 3 * theoretical_crossing(r, s) + 10))
               is not None for r, s in zip(ordered, ordered[1:]))


if __name__ == "__main__":
    slopes = [0.5, 0.5001, 1.0, math.sqrt(2), math.e / 2, 3.7]
    print(f"{'r':>10} {'s':>10} {'bound':>10} {'observed':>10}")
    for r, s, bound, obs in separation_table(slopes):
        print(f"{r:10.5f} {s:10.5f} {bound:10d} {str(obs):>10}")
    print("strictly increasing chain:", chain_is_strictly_increasing(slopes))
    for level in (10, 1000, 10 ** 6):
        print(f"S_0.5 exceeds {level:>8} from coordinate {unlimited_certificate(0.5, level)}")

