function SAME-GALAXY(f, g, horizon, max_shift):
    n <- 0
    while n <= max_shift:
        up   <- CERTIFIED( i -> g(i) <= f(i) + n , horizon )
        down <- CERTIFIED( i -> f(i) <= g(i) + n , horizon )
        if up and down: return n                 // admissible standard shift
        n <- 1 if n = 0 else 2n
    return NONE                                  // different galaxies

function FAR-ABOVE(f, g, levels, horizon):
    return for all n < levels: CERTIFIED( i -> f(i) + n < g(i) , horizon ) exists

function GALAXY-MIDPOINT(f, g):
    return i -> f(i) + floor( (g(i) - f(i)) / 2 )   // density witness

function COMPOSITE-CENTRE(i):  return i! + floor(i/2)

function WINDOW-ALL-COMPOSITE(i, m):
    c <- COMPOSITE-CENTRE(i)
    return for all d in [-m, m]: c + d is composite

function PRIME-FREE-THRESHOLD(m, search, confirm):
    for i <- 3 .. search:
        if WINDOW-ALL-COMPOSITE(j, m) for all j in [i, i+confirm):
            return (2m + 8, i)          // theoretical bound, observed threshold
